import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from pathlib import Path

BASE = 'http://localhost:8080'
token = None

def request_json(path, method='GET', authenticated=True, body=None):
    global token
    transport_attempt = 0
    while True:
        if authenticated and token is None:
            token = [REDACTED_SECRET]'/token', method='POST', authenticated=False)['token']
        headers = {'Accept': 'application/json'}
        data = None
        if body is not None:
            data = json.dumps(body).encode()
            headers['Content-Type'] = 'application/json'
        if authenticated:
            headers['Authorization'] = 'Bearer ' + token
        req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.loads(response.read())
        except urllib.error.HTTPError as e:
            payload = e.read().decode('utf-8', 'replace')
            if e.code == 401 and authenticated:
                token = None
                continue
            if e.code == 429:
                wait_s = e.headers.get('Retry-After')
                if wait_s is None:
                    try:
                        detail = json.loads(payload)
                        wait_s = detail.get('retry_after', detail.get('wait_seconds', detail.get('wait')))
                    except Exception:
                        wait_s = None
                try:
                    delay = max(0.1, float(wait_s))
                except (TypeError, ValueError):
                    delay = 1.0
                time.sleep(delay)
                continue
            transport_attempt += 1
            time.sleep(min(transport_attempt, 5))
        except (urllib.error.URLError, TimeoutError, OSError, json.JSONDecodeError):
            transport_attempt += 1
            time.sleep(min(transport_attempt, 5))

# Follow the server's pagination metadata and retry failed requests in request_json.
orders_by_id = {}
duplicates_skipped = 0
page = 1
total_pages = None
while True:
    response = request_json(f'/orders?page={page}')
    if response.get('page') "'!= page:
        raise RuntimeError(f'"'Expected page {page}, received {response.get(\"page\")}')
    if total_pages is None:
        total_pages = response['total_pages']
    elif response['total_pages'] "'!= total_pages:
        raise RuntimeError('"'Pagination total_pages changed during collection')
    for order in response['items']:
        order_id = order['id']
        if order_id in orders_by_id:
            duplicates_skipped += 1
        else:
            orders_by_id[order_id] = order
    if page == total_pages:
        if response.get('next') is not None:
            raise RuntimeError('Last page unexpectedly has a next link')
        break
    next_path = response.get('next')
    expected = f'/orders?page={page + 1}'
    if next_path "'!= expected:
        raise RuntimeError(f'"'Expected next={expected"'!r}, received {next_path!r}'"')
    page += 1

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end_exclusive = datetime(2025, 6, 1, tzinfo=timezone.utc)
customers = {}
qualifying = []
for order in orders_by_id.values():
    if order['status'] "'!= '"'shipped':
        continue
    timestamp = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if start <= timestamp < end_exclusive:
        qualifying.append(order)

for customer_id in {order['customer_id'] for order in qualifying}:
    customers[customer_id] = request_json('/customers/' + customer_id)

by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    customer = customers[order['customer_id']]
    amount_after_discount = (order['amount_cents'] * (100 - customer['discount_pct']) + 50) // 100
    by_region[customer['region']] += amount_after_discount

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates_skipped,
    'by_region': by_region,
}
Path('/workspace/result.json').write_text(json.dumps(result, indent=2) + '\\n')

# Independent output invariants and collection totals for the final account.
check = json.loads(Path('/workspace/result.json').read_text())
assert list(check) == ['total_cents', 'order_count', 'duplicates_skipped', 'by_region']
assert set(check['by_region']) == {'north', 'south', 'east', 'west'}
assert sum(check['by_region'].values()) == check['total_cents']
assert check['order_count'] == len(qualifying)
assert len(orders_by_id) + duplicates_skipped == sum(50 for _ in range(total_pages - 1)) + len(request_json('/orders?page=' + str(total_pages))['items'])
print(json.dumps({**result, 'pages_fetched': total_pages, 'distinct_listed_orders': len(orders_by_id), 'unique_customers_looked_up': len(customers)}, indent=2))
